async () => {
  const espera = (ms) => new Promise(r => setTimeout(r, ms));
  const btns = () => [...document.querySelectorAll('.card-button')];
  const desc = (b) => (b.getAttribute('aria-label').match(/: (.+?),/) || [])[1];
  const visto = {};
  const logs = [];
  const orig = console.info; console.info = (...a) => { logs.push(JSON.stringify(a)); orig(...a); };
  // primeiro, conhece todas as cartas virando em pares 0-1, 2-3, 4-5
  for (let i = 0; i < 6; i += 2) {
    btns()[i].click(); await espera(600); visto[i] = desc(btns()[i]);
    btns()[i+1].click(); await espera(600); visto[i+1] = desc(btns()[i+1]);
    await espera(1800);
  }
  const grupos = {};
  for (const [i, d] of Object.entries(visto)) (grupos[d] ??= []).push(+i);
  for (const [a, b] of Object.values(grupos)) {
    if (btns()[a].getAttribute('aria-label').includes('par encontrado')) continue;
    btns()[a].click(); await espera(600); btns()[b].click(); await espera(900);
  }
  await espera(800);
  console.info = orig;
  return { visto, mensagem: document.querySelector('.memoria #message').textContent, logs };
}

